using System.Windows;
using System.Windows.Controls;
namespace WoWItemEditor;
internal sealed class QuestEditorWindow : Window
{
    private readonly QuestForm form;private readonly TextBox npcName=new();private readonly TextBlock feedback=DesignerWindow.Text("Loading quest…",12),position=DesignerWindow.Text("",12);private readonly ComboBox characters=new();private readonly Button save=new(){Content="Review & save quest",IsEnabled=false};private QuestEditSession? session;private QuestPlacement? move;private bool busy;private readonly CatalogResult catalog;internal Task Ready=>ready.Task;private readonly TaskCompletionSource ready=new();
    internal QuestEditorWindow(CatalogResult catalog,CreatedQuest entry,QuestEditSession? prepared=null){this.catalog=catalog;Title=$"Edit created quest · {entry.Title}";Width=1400;Height=960;MinWidth=1100;MinHeight=760;Background=TooltipView.Brush("#232428");WindowStartupLocation=WindowStartupLocation.CenterOwner;form=new(catalog);var root=new DockPanel{Margin=new Thickness(18)};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(DesignerWindow.Text($"EDIT QUEST {entry.QuestId} · NPC {entry.NpcId}",21));var rename=new DockPanel{Margin=new Thickness(0,8,0,8)};top.Children.Add(rename);var label=DesignerWindow.Text("Copied NPC name",12);label.Margin=new Thickness(0,0,12,0);DockPanel.SetDock(label,Dock.Left);rename.Children.Add(label);rename.Children.Add(npcName);top.Children.Add(position);var actions=new WrapPanel();top.Children.Add(actions);characters.Width=240;actions.Children.Add(characters);DesignerWindow.Button("Move NPC to saved character location…",actions).Click+=async(_,_)=>await Capture();DesignerWindow.Button("Keep current position",actions).Click+=(_,_)=>{move=null;ShowPosition();};DesignerWindow.Button("Check quest / ! availability",actions).Click+=async(_,_)=>await Check();var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);feedback.TextWrapping=TextWrapping.Wrap;bottom.Children.Add(feedback);var buttons=new WrapPanel();bottom.Children.Add(buttons);buttons.Children.Add(save);DesignerWindow.Button("Close",buttons).Click+=(_,_)=>Close();root.Children.Add(form);save.Click+=async(_,_)=>await Save();Loaded+=async(_,_)=>{try{session=prepared??await QuestEditing.Load(entry);npcName.Text=session.Draft.NpcName;await form.Bind(session.Draft);characters.ItemsSource=await CharacterRepository.ListAsync();characters.SelectedIndex=0;ShowPosition();save.IsEnabled=true;feedback.Text="Edit the existing quest. Changing objectives is blocked while characters have it active. Saved changes require a worldserver restart.";}catch(Exception ex){feedback.Text="Could not load quest: "+ex.Message;}finally{ready.TrySetResult();}};Closing+=(_,e)=>e.Cancel=busy;}
    private void ShowPosition(){position.Text=move?.Summary??(session is null?"":$"Current spawn: map {session.Spawn["map"]} · X {session.Spawn["position_x"]} · Y {session.Spawn["position_y"]} · Z {session.Spawn["position_z"]} · facing {session.Spawn["orientation"]}");}
    private async Task Capture(){if(characters.SelectedItem is not CharacterInfo hero)return;var prompt=new Window{Title="Capture placement",Width=700,Height=310,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Background};var panel=new StackPanel{Margin=new Thickness(20)};prompt.Content=panel;var text=DesignerWindow.Text("Log into WoW with this character. Stand on solid outdoor ground at the intended NPC location and face the direction it should face. Log out to character selection to save coordinates. Keep the character logged out until you save. Capturing replaces only the NPC's position after review.",15);text.TextWrapping=TextWrapping.Wrap;panel.Children.Add(text);var confirmed=new CheckBox{Content="I completed these steps and was standing on solid ground."};panel.Children.Add(confirmed);DesignerWindow.Button("Capture saved location",panel).Click+=(_,_)=>{if(confirmed.IsChecked==true)prompt.DialogResult=true;};if(prompt.ShowDialog()!=true)return;try{move=await QuestCreation.Capture(hero.Guid);ShowPosition();feedback.Text="New position captured; it will be applied only when you save.";}catch(Exception ex){feedback.Text=ex.Message;}}
    private async Task Check(){if(session is null||characters.SelectedItem is not CharacterInfo hero)return;try{feedback.Text="Checking availability…";feedback.Text=await QuestAvailability.Check(form.Draft(npcName.Text),hero,session.Entry.QuestId,session.Entry.NpcId);}catch(Exception ex){feedback.Text=ex.Message;}}
    private async Task Save(){if(session is null||busy)return;busy=true;save.IsEnabled=false;((UIElement)Content).IsEnabled=false;try{var draft=form.Draft(npcName.Text);QuestCreation.ValidateContent(draft);var review=new ContentReviewWindow("Edit created quest",draft.Title,form.Review(session.Draft),form.Review(draft)+(move is null?"":"\n\nMOVE NPC\n"+move.Summary)){Owner=this};if(review.ShowDialog()!=true)return;feedback.Text="Saving quest, objectives, rewards and edit history…";await QuestEditing.Save(session,draft,move);session=await QuestEditing.Load(session.Entry);move=null;ShowPosition();feedback.Text="Saved. Restart the worldserver and test the quest in WoW. Editing does not reset completed quests or grant rewards again.";}catch(Exception ex){feedback.Text="Could not save: "+ex.Message;}finally{busy=false;save.IsEnabled=session is not null;((UIElement)Content).IsEnabled=true;}}
}
